const {chromium}=require(process.env.PLAYWRIGHT_MODULE); const fs=require('node:fs');
(async()=>{const browser=await chromium.launch({executablePath:process.env.CHROME_PATH,headless:true});try{const page=await browser.newPage();await page.goto('http://127.0.0.1:8191');const bytes=await page.evaluate(async()=>{const c=document.createElement('canvas');c.width=128;c.height=128;document.body.append(c);const ctx=c.getContext('2d');ctx.fillStyle='blue';ctx.fillRect(0,0,128,128);const stream=c.captureStream(0);const track=stream.getVideoTracks()[0];const recorder=new MediaRecorder(stream,{mimeType:'video/webm;codecs=vp8'});const chunks=[];recorder.ondataavailable=e=>chunks.push(e.data);const done=new Promise(resolve=>recorder.onstop=resolve);recorder.start();for(let i=0;i<30;i++){ctx.fillStyle=i%2?'blue':'red';ctx.fillRect(0,0,128,128);track.requestFrame();await new Promise(resolve=>setTimeout(resolve,60));}recorder.stop();await done;track.stop();c.remove();return Array.from(new Uint8Array(await new Blob(chunks).arrayBuffer()));});if(bytes.length<200)throw Error('Empty recording');fs.writeFileSync('tests/fixtures/viewer.webm',Buffer.from(bytes));console.log(bytes.length+' bytes');}finally{await browser.close();}})().catch(e=>{console.error(e);process.exit(1)});
